#!/usr/bin/env python3

from cryptography.hazmat.primitives.serialization import load_pem_public_key
from cryptography.hazmat.primitives import serialization
import gmpy2
import os

def os2ip(octet_string):
    return int.from_bytes(octet_string, byteorder='big')

def i2osp(integer, length):
    if isinstance(integer, gmpy2.mpz):
        integer = int(integer)
    return int.to_bytes(integer, length=length, byteorder='big')

def read_pubkey(pubkey_path):
    with open(pubkey_path, 'rb') as f:
        key_data = f.read()
    pubkey = load_pem_public_key(key_data)
    return pubkey.public_numbers().n

def process_key(key_path):
    with open(key_path, 'rb') as f:
        key_data = f.read()
    return os2ip(key_data)

def find_cube_root(n):
    return gmpy2.iroot(n, 3)[0]

def get_flag(key_bytes, ciphertext):
    return bytes([a ^ b for a, b in zip(key_bytes, ciphertext)])

def main():
    try:
        # Read files
        N = read_pubkey('ctf_files/pubkey.pem')
        Y = process_key('ctf_files/key.enc')

        with open('ctf_files/file.enc', 'rb') as f:
            ciphertext = f.read()

        # Calculate Y + N
        Y_plus_N = Y + N

        # Find cube root (since e=3)
        K = find_cube_root(Y_plus_N)

        # Convert K back to octet string
        K_bytes = i2osp(K, 192)  # 192 bytes as specified

        # XOR with ciphertext to get flag
        flag = get_flag(K_bytes, ciphertext)

        print(flag.decode('utf-8', errors='ignore'))
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    main()
